export interface StockChange {
  sku: string;
  quantity: number;
  reason: string;
}

export interface StockEntry extends StockChange {
  id: string;
}

export class StockLedger {
  private readonly data: StockEntry[] = [];
  private nextId = 1;

  constructor(initial: readonly StockChange[] = []) {
    for (const change of initial) this.record(change);
  }

  record(change: StockChange): StockEntry {
    const sku = StockLedger.normalizeSku(change.sku);
    const reason = typeof change.reason === "string" ? change.reason.trim() : "";
    if (reason.length === 0) throw new TypeError("reason must be nonempty");
    if (!Number.isSafeInteger(change.quantity) || change.quantity === 0) {
      throw new TypeError("quantity must be a nonzero safe integer");
    }

    const entry: StockEntry = {
      id: `E${this.nextId}`,
      sku,
      quantity: change.quantity,
      reason,
    };
    this.data.push(entry);
    this.nextId += 1;
    return { ...entry };
  }

  entriesFor(sku: string): StockEntry[] {
    const normalized = StockLedger.normalizeSku(sku);
    return this.data.filter((entry) => entry.sku === normalized);
  }

  balanceFor(sku: string): number {
    const normalized = StockLedger.normalizeSku(sku);
    return this.data.reduce(
      (sum, entry) => entry.sku === normalized ? sum + entry.quantity : sum,
      0,
    );
  }

  private static normalizeSku(value: string): string {
    if (typeof value !== "string") throw new TypeError("sku must be a string");
    const sku = value.trim();
    if (!/^[A-Za-z0-9_-]+$/.test(sku)) throw new TypeError("invalid sku");
    return sku;
  }
}

