import { StockLedger, type StockChange, type StockEntry } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const empty = new StockLedger();
equal(empty.entriesFor("ABC"), [], "empty entries");
equal(empty.balanceFor(" ABC "), 0, "empty balance");

const initial: StockChange[] = [
  { sku: " A-1 ", quantity: 5, reason: " received " },
  { sku: "A-1", quantity: -2, reason: " sold " },
  { sku: "B_2", quantity: 7, reason: "opening" },
];
const originalInitial = JSON.stringify(initial);
const ledger = new StockLedger(initial);
equal(initial, JSON.parse(originalInitial), "constructor input remains unchanged");
equal(ledger.entriesFor(" A-1 "), [
  { id: "E1", sku: "A-1", quantity: 5, reason: "received" },
  { id: "E2", sku: "A-1", quantity: -2, reason: "sold" },
], "initial records and insertion order");
equal(ledger.balanceFor("A-1"), 3, "balance sums changes");

const change: StockChange = { sku: " C_3 ", quantity: 4, reason: " restock " };
const added: StockEntry = ledger.record(change);
equal(added, { id: "E4", sku: "C_3", quantity: 4, reason: "restock" }, "record snapshot");
equal(change, { sku: " C_3 ", quantity: 4, reason: " restock " }, "record input unchanged");
(added as { reason: string }).reason = "corrupted";
equal(ledger.entriesFor("C_3"), [{ id: "E4", sku: "C_3", quantity: 4, reason: "restock" }], "record result is detached");
const firstRead = ledger.entriesFor("A-1");
(firstRead[0] as { quantity: number }).quantity = 999;
firstRead.push({ id: "fake", sku: "A-1", quantity: 1, reason: "fake" });
equal(ledger.balanceFor("A-1"), 3, "returned array and entries are detached");
assert(ledger.entriesFor("A-1")[0] !== ledger.entriesFor("A-1")[0], "lookups return fresh entries");

const before = ledger.entriesFor("A-1");
throwsType(() => ledger.record({ sku: " ", quantity: 1, reason: "x" }), "blank sku");
throwsType(() => ledger.record({ sku: "bad sku", quantity: 1, reason: "x" }), "invalid sku characters");
throwsType(() => ledger.record({ sku: "A", quantity: 0, reason: "x" }), "zero quantity");
throwsType(() => ledger.record({ sku: "A", quantity: 1.5, reason: "x" }), "fractional quantity");
throwsType(() => ledger.record({ sku: "A", quantity: Number.MAX_SAFE_INTEGER + 1, reason: "x" }), "unsafe quantity");
throwsType(() => ledger.record({ sku: "A", quantity: 1, reason: "  " }), "blank reason");
equal(ledger.entriesFor("A-1"), before, "failed records do not change state");
const afterFailures = ledger.record({ sku: "Z", quantity: -1, reason: "adjust" });
assert(afterFailures.id === "E5", "failed records do not consume IDs");
throwsType(() => ledger.entriesFor("bad sku"), "invalid lookup sku");
throwsType(() => ledger.balanceFor(""), "blank balance lookup");

